# SPDX-License-Identifier: Apache-2.0
import base64, contextlib, datetime, hashlib, importlib.util, io, json, os, pathlib, stat, subprocess, sys, tempfile, time, unittest
P = pathlib.Path
uid = os.getuid()
assert uid == os.geteuid() == 501 and os.stat('/dev/console').st_uid == uid, 'human console/SSH identity differs'
os.umask(0o077)
parent = P.home() / 'code/airk/artifacts'
assert parent.resolve() == parent and parent.stat().st_uid == uid and os.access(parent, os.R_OK | os.W_OK | os.X_OK)
assert not parent.stat().st_mode & 0o022, 'output parent writable by group/other'
root = parent / 'mac-script-resume-r1'
assert not root.exists(), 'fresh output required'
root.mkdir(mode=0o700)
assert root.stat().st_uid == uid and stat.S_IMODE(root.stat().st_mode) == 0o700
packet = json.loads(base64.b64decode(''))
source = root / 'source'
source.mkdir(mode=0o700)
for relative, row in packet.items():
    path = source / relative
    assert path.is_relative_to(source) and '..' not in P(relative).parts
    cursor = source
    for part in P(relative).parts[:-1]:
        cursor = cursor / part
        if not cursor.exists(): cursor.mkdir(mode=0o700)
        assert cursor.stat().st_uid == uid and not cursor.is_symlink()
    raw = base64.b64decode(row['base64'])
    assert len(raw) == row['bytes'] and hashlib.sha256(raw).hexdigest() == row['sha256']
    with path.open('xb') as stream: stream.write(raw)
    assert path.stat().st_uid == uid and hashlib.sha256(path.read_bytes()).hexdigest() == row['sha256']
tmp = root / 'tmp'
tmp.mkdir(mode=0o700)
cache = root / 'clang-cache'
cache.mkdir(mode=0o700)
os.environ.update(TMPDIR=str(tmp), TMP=str(tmp), TEMP=str(tmp), CLANG_MODULE_CACHE_PATH=str(cache), PYTHONDONTWRITEBYTECODE='1')
tempfile.tempdir = str(tmp)
policy = json.loads((source/'scripts/signing-identity.json').read_bytes())['macos']
os.environ['AIRK_TEST_MAC_SIGNING_IDENTITY'] = policy['identity']
os.environ['AIRK_TEST_MAC_TEAM_ID'] = policy['team_id']
def audit():
    assert os.getuid() == os.geteuid() == uid and os.stat('/dev/console').st_uid == uid
    count = 0
    for path in [root, *root.rglob('*')]:
        st = path.lstat()
        assert st.st_uid == uid and not stat.S_ISLNK(st.st_mode), 'foreign owner/alias: '+str(path)
        count += 1
    return count
original_run = subprocess.run
commands = []
def observed_run(args, *a, **kw):
    audit()
    entry = {'argv': [str(x) for x in args], 'started_utc': datetime.datetime.now(datetime.timezone.utc).isoformat()}
    commands.append(entry)
    started = time.monotonic()
    try:
        result = original_run(args, *a, **kw)
        entry['exit_code'] = result.returncode
        return result
    finally:
        entry['elapsed_seconds'] = time.monotonic()-started
        entry['owner_audit_entries'] = audit()
subprocess.run = observed_run
class RetainedTemporaryDirectory(tempfile.TemporaryDirectory):
    def cleanup(self): self._finalizer.detach()
tempfile.TemporaryDirectory = RetainedTemporaryDirectory
spec = importlib.util.spec_from_file_location('mac_runtime_tests', source/'scripts/tests/test_service_runtime_build.py')
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)
names = ['test_development_mac_helper_loads_its_adhoc_signed_library', 'test_standalone_launcher_remains_valid_after_sealing_and_copying', 'test_developer_id_standalone_launcher_survives_sealed_copy']
report = {'schema':'airk.private.mac-script-resume/1', 'started_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(), 'identity':{'uid':uid,'euid':os.geteuid(),'console_uid':os.stat('/dev/console').st_uid}, 'python':sys.version, 'source_files':{k:{'sha256':v['sha256'],'bytes':v['bytes']} for k,v in packet.items()}, 'tests':[], 'commands':commands, 'scope':'Three historical Mac standalone launcher/library fixtures; no Cargo, modern installation, notarization upload or model qualification', 'passed':False}
started = time.monotonic()
try:
    for name in names:
        log = io.StringIO()
        t0 = time.monotonic()
        with contextlib.redirect_stdout(log), contextlib.redirect_stderr(log):
            result = unittest.TextTestRunner(stream=log, verbosity=2).run(unittest.TestSuite([module.ServiceRuntimeBuildTests(name)]))
        logfile = root/(name+'.log')
        logfile.write_text(log.getvalue())
        entry={'name':name,'selected':result.testsRun,'failed':len(result.failures),'errors':len(result.errors),'skipped':result.skipped,'elapsed_seconds':time.monotonic()-t0,'log_sha256':hashlib.sha256(logfile.read_bytes()).hexdigest()}
        report['tests'].append(entry)
        assert result.testsRun == 1 and result.wasSuccessful() and not result.skipped, 'selected Mac test nonpass: '+name
    report['passed']=True
except BaseException as error:
    report['failure']={'type':type(error).__name__,'message':str(error)}
finally:
    report['elapsed_seconds']=time.monotonic()-started
    report['owner_audit_entries']=audit()
    report['final_source_hashes']={k:hashlib.sha256((source/k).read_bytes()).hexdigest() for k in packet}
    assert report['final_source_hashes']=={k:v['sha256'] for k,v in packet.items()}
    report['retained_outputs']=[{'path':str(p.relative_to(root)),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'uid':p.stat().st_uid} for p in root.rglob('*') if p.is_file()]
    report['ended_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat()
    (root/'receipt.json').write_text(json.dumps(report,indent=2)+'\n')
    audit()
print(json.dumps({'root':str(root),'receipt':report}))
sys.exit(0 if report['passed'] else 1)